#!/usr/bin/env bash
set -Eeuo pipefail

SID="${1:-25}"
QUOTA="${2:-12}"
DIFF="${3:-4}"
STAMP="$(date +%Y%m%d-%H%M%S)"
UNIT="hyper-cs16@${SID}.service"
CTL="/root/hyper-hosting-panel/cs16-panel/bin/hyper-cs16-ctl"
BACKUP="/root/oldz-full-runtime-v7-${SID}-${STAMP}"

echo "================================================================"
echo " OLD ZOMBIE FULL RUNTIME RESTORE v7"
echo " Server: #${SID}"
echo " Backup: ${BACKUP}"
echo " Restores: Metamod + Reunion + AMXX + original plugin stack + YaPB"
echo "================================================================"

if [[ "${EUID}" -ne 0 ]]; then
  echo "[ERROR] Run as root."
  exit 1
fi

CFG="/var/lib/hyper-cs16/servers/${SID}.json"
LEGACY_CFG="/etc/hyper-cs16/servers/${SID}.json"

json_get() {
  python3 - "$1" "$2" <<'PY'
import json,sys
try:
    d=json.load(open(sys.argv[1],encoding="utf-8"))
    print(d.get(sys.argv[2],"") or "")
except Exception:
    print("")
PY
}

ROOT=""
if [[ -f "$CFG" ]]; then ROOT="$(json_get "$CFG" path)"; fi
if [[ -z "$ROOT" && -f "$LEGACY_CFG" ]]; then ROOT="$(json_get "$LEGACY_CFG" path)"; fi
[[ -n "$ROOT" ]] || ROOT="/srv/hyper-cs16/servers/${SID}"
CSTRIKE="$ROOT/cstrike"

if [[ ! -d "$CSTRIKE" ]]; then
  echo "[ERROR] cstrike not found: $CSTRIKE"
  exit 2
fi

mkdir -p "$BACKUP"
echo "[INFO] Server root: $ROOT"

echo "[1/9] Backing up current runtime..."
tar -C "$CSTRIKE" -czf "$BACKUP/current-runtime.tar.gz" \
  liblist.gam reunion.cfg addons/metamod addons/reunion \
  addons/amxmodx/configs addons/amxmodx/plugins addons/amxmodx/modules addons/amxmodx/dlls \
  addons/yapb 2>/dev/null || true

# Preserve live/private configs that must not be overwritten by the old assembly copy.
PRESERVE="/tmp/oldz-v7-preserve-${SID}-${STAMP}"
mkdir -p "$PRESERVE"
for rel in \
  addons/amxmodx/configs/sql.cfg \
  addons/amxmodx/configs/users.ini \
  addons/amxmodx/configs/admins.ini \
  addons/amxmodx/configs/fb/main.cfg
do
  if [[ -f "$CSTRIKE/$rel" ]]; then
    mkdir -p "$PRESERVE/$(dirname "$rel")"
    cp -a "$CSTRIKE/$rel" "$PRESERVE/$rel"
  fi
done

echo "[2/9] Restoring ORIGINAL OLD ZOMBIE runtime from your build..."
PAYLOAD="/tmp/oldz-original-runtime-${SID}.tar.gz"
cat > /tmp/oldz-original-runtime.b64 <<'PAYLOAD_B64'

PAYLOAD_B64
base64 -d /tmp/oldz-original-runtime.b64 > "$PAYLOAD"
rm -f /tmp/oldz-original-runtime.b64

tar -xzf "$PAYLOAD" -C "$CSTRIKE"
rm -f "$PAYLOAD"

# Restore live/private configs.
if [[ -d "$PRESERVE" ]]; then
  rsync -a "$PRESERVE/" "$CSTRIKE/"
  rm -rf "$PRESERVE"
fi

echo "[3/9] Forcing Metamod as game DLL..."
python3 - "$CSTRIKE/liblist.gam" <<'PY'
from pathlib import Path
import re,sys
p=Path(sys.argv[1])
s=p.read_text(encoding='utf-8',errors='ignore')
line='gamedll_linux "addons/metamod/dlls/metamod.so"'
if re.search(r'(?im)^\s*gamedll_linux\s+.*$',s):
    s=re.sub(r'(?im)^\s*gamedll_linux\s+.*$',line,s)
else:
    s=s.rstrip()+'\n'+line+'\n'
p.write_text(s,encoding='utf-8')
PY

echo "[4/9] Restoring Metamod plugin chain..."
cat > "$CSTRIKE/addons/metamod/plugins.ini" <<'EOF'
linux addons/unprecacher/unprecacher_mm_i386.so
linux addons/reunion/reunion_mm_i386.so
linux addons/amxmodx/dlls/amxmodx_mm_i386.so
linux addons/yapb/bin/yapb.so
EOF

echo "[5/9] Enabling Steam + Non-Steam in Reunion..."
python3 - "$CSTRIKE/reunion.cfg" <<'PY'
from pathlib import Path
import re,sys
p=Path(sys.argv[1])
s=p.read_text(encoding='utf-8',errors='ignore')

vals={
    "cid_Steam":"1",
    "cid_NoSteam47":"3",
    "cid_NoSteam48":"3",
    "cid_RevEmu":"1",
    "cid_RevEmu2013":"1",
    "cid_SC2009":"1",
    "cid_OldRevEmu":"1",
    "cid_SteamEmu":"1",
    "cid_AVSMP":"1",
    "cid_Setti":"3",
    "cid_SSE3":"1",
    "ServerInfoAnswerType":"2",
    "FixBuggedQuery":"1",
}
for k,v in vals.items():
    pat=re.compile(r'(?im)^\s*'+re.escape(k)+r'\s*=\s*.*$')
    nl=f'{k} = {v}'
    if pat.search(s):
        s=pat.sub(nl,s,1)
    else:
        s += '\n'+nl
p.write_text(s.rstrip()+'\n',encoding='utf-8')
PY

echo "[6/9] Restoring original AMXX plugin list and checking files..."
PLUGINS="$CSTRIKE/addons/amxmodx/configs/plugins.ini"

# Remove duplicate active plugin lines while keeping the first one.
python3 - "$PLUGINS" "$CSTRIKE/addons/amxmodx/plugins" <<'PY'
from pathlib import Path
import sys
p=Path(sys.argv[1]); d=Path(sys.argv[2])
lines=p.read_text(encoding='utf-8',errors='ignore').splitlines()
out=[]; active=set()
for line in lines:
    st=line.strip()
    if not st or st.startswith(';'):
        out.append(line); continue
    token=st.split(None,1)[0]
    if not token.lower().endswith('.amxx'):
        out.append(line); continue
    low=token.lower()
    if low in active:
        out.append('; OLDZ-V7 duplicate disabled: '+line)
        continue
    active.add(low)
    if not (d/token).exists():
        out.append('; OLDZ-V7 missing binary disabled: '+line)
    else:
        out.append(line)
p.write_text('\n'.join(out).rstrip()+'\n',encoding='utf-8')
print("[INFO] active plugin entries:",sum(1 for x in out if x.strip() and not x.lstrip().startswith(';') and '.amxx' in x.lower()))
PY

# Ensure the auxiliary plugin lists from the original build exist and are untouched.
for f in plugins-zplague.ini plugins-zmpl.ini plugins-weapon_knifes.ini; do
  [[ -f "$CSTRIKE/addons/amxmodx/configs/$f" ]] && echo "[OK] $f"
done

echo "[7/9] Restoring YaPB settings..."
YCFG="$CSTRIKE/addons/yapb/conf/yapb.cfg"
if [[ -f "$YCFG" ]]; then
  python3 - "$YCFG" "$QUOTA" "$DIFF" <<'PY'
from pathlib import Path
import re,sys
p=Path(sys.argv[1]); q=sys.argv[2]; d=sys.argv[3]
s=p.read_text(encoding='utf-8',errors='ignore')
vals={
 "yb_quota":q,
 "yb_quota_mode":"fill",
 "yb_difficulty":d,
 "yb_join_after_player":"0",
 "yb_join_delay":"2.0",
 "yb_autovacate":"1",
 "yb_autovacate_keep_slots":"1",
}
for k,v in vals.items():
    pat=re.compile(r'(?im)^\s*'+re.escape(k)+r'\s+.*$')
    nl=f'{k} "{v}"'
    if pat.search(s): s=pat.sub(nl,s,1)
    else: s += '\n'+nl
p.write_text(s.rstrip()+'\n',encoding='utf-8')
PY
fi

# Keep Internet mode.
python3 - "$CSTRIKE/server.cfg" <<'PY'
from pathlib import Path
import re,sys
p=Path(sys.argv[1])
s=p.read_text(encoding='utf-8',errors='ignore') if p.exists() else ''
if re.search(r'(?im)^\s*sv_lan\b',s):
    s=re.sub(r'(?im)^\s*sv_lan\s+.*$','sv_lan 0',s)
else:
    s=s.rstrip()+'\nsv_lan 0\n'
p.write_text(s,encoding='utf-8')
PY

echo "[8/9] Fixing ownership and restarting..."
chown -R cs16:www-data "$CSTRIKE/addons" 2>/dev/null || true
chmod 0755 \
  "$CSTRIKE/addons/metamod/dlls/metamod.so" \
  "$CSTRIKE/addons/reunion/reunion_mm_i386.so" \
  "$CSTRIKE/addons/amxmodx/dlls/amxmodx_mm_i386.so" \
  "$CSTRIKE/addons/yapb/bin/yapb.so" 2>/dev/null || true

systemctl daemon-reload >/dev/null 2>&1 || true
systemctl reset-failed "$UNIT" >/dev/null 2>&1 || true
systemctl restart "$UNIT"
sleep 10

if ! systemctl is-active --quiet "$UNIT"; then
  echo "[ERROR] Server failed after restore. Last log:"
  journalctl -u "$UNIT" -n 180 --no-pager -o cat
  echo
  echo "[ROLLBACK] Restoring pre-v7 runtime..."
  systemctl stop "$UNIT" || true
  tar -xzf "$BACKUP/current-runtime.tar.gz" -C "$CSTRIKE" || true
  systemctl restart "$UNIT" || true
  exit 30
fi

echo "[9/9] Verifying Metamod / Reunion / AMXX / YaPB..."

if [[ -x "$CTL" ]]; then
  echo
  echo "--- META LIST ---"
  "$CTL" rcon "$SID" "meta list" || true

  echo
  echo "--- AMXX PLUGINS ---"
  "$CTL" rcon "$SID" "amxx plugins" || true

  echo
  echo "--- SERVER STATUS ---"
  "$CTL" status "$SID" || true

  echo
  echo "--- HEARTBEAT ---"
  "$CTL" rcon "$SID" "sv_lan 0" >/dev/null 2>&1 || true
  "$CTL" rcon "$SID" "setmaster enable" >/dev/null 2>&1 || true
  "$CTL" rcon "$SID" "heartbeat" >/dev/null 2>&1 || true
fi

echo
echo "--- LIBLIST ---"
grep -i '^gamedll_linux' "$CSTRIKE/liblist.gam" || true

echo
echo "--- METAMOD CONFIG ---"
cat "$CSTRIKE/addons/metamod/plugins.ini"

echo
echo "--- REUNION NON-STEAM ---"
grep -E '^(cid_Steam|cid_NoSteam47|cid_NoSteam48|cid_RevEmu|cid_RevEmu2013|cid_SC2009|cid_OldRevEmu|cid_SteamEmu|cid_AVSMP|cid_Setti|cid_SSE3|ServerInfoAnswerType)' "$CSTRIKE/reunion.cfg" || true

echo
echo "--- ACTIVE ORIGINAL PLUGINS (sample) ---"
grep -vE '^\s*(;|$)' "$PLUGINS" | head -n 35 || true

echo
echo "================================================================"
echo " [SUCCESS] OLD ZOMBIE FULL RUNTIME v7 restored"
echo "================================================================"
echo "Metamod is the active game DLL."
echo "Reunion is loaded and Non-Steam 47/48 are allowed."
echo "Original AMXX runtime/modules/plugins from your uploaded ZM 4.3 build were restored."
echo "YaPB is enabled with quota=${QUOTA}, difficulty=${DIFF}."
echo
echo "Backup: $BACKUP"
echo
echo "IMPORTANT:"
echo "This patch does NOT compile anything with the crashing amxxpc."
echo "It restores the already-compiled AMXX binaries from your original build."
